type Route={name:string;params?:any};
const money=(v:any)=>Number(v||0).toLocaleString('fa-IR');
const titleOf=(x:any)=>x?.title||x?.name||x?.label||'';

const faInput=(v:any)=>String(v??'').replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]); const latinInput=(v:string)=>v.replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
function Field({value,onChangeText,placeholder,keyboardType='default',multiline=false}:any){const numeric=keyboardType==='number-pad'||keyboardType==='numeric'||keyboardType==='decimal-pad';return <TextInput value={numeric?faInput(value):value} onChangeText={(v:string)=>onChangeText(numeric?latinInput(v):v)} placeholder={placeholder} placeholderTextColor={palette.text2} keyboardType={keyboardType} multiline={multiline} style={[s.input,multiline&&{height:110,textAlignVertical:'top'}]}/>}
function Chip({label,active,onPress}:any){return <Pressable onPress={onPress} style={[s.chip,active&&s.chipActive]}><Txt style={[s.chipText,active&&{color:palette.primaryDark,fontWeight:'900'}]}>{label}</Txt></Pressable>}
function Stat({value,label}:any){return <View style={s.stat}><Txt style={s.statValue}>{value}</Txt><Txt style={s.statLabel}>{label}</Txt></View>}
function SectionTitle({title,more,onMore}:any){return <View style={s.sectionHead}><Txt style={s.sectionTitle}>{title}</Txt>{more?<Pressable onPress={onMore}><Txt style={{color:palette.primary,fontWeight:'800'}}>{more}</Txt></Pressable>:null}</View>}

function Login({onLoggedIn}:any){
 const [privacyOpen,setPrivacyOpen]=useState(false);
 const [privacyAccepted,setPrivacyAccepted]=useState(false);
 const [pendingTicket,setPendingTicket]=useState('');
 const consent=useRef(false);
 const loginBusy=useRef(false);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState('');
 const exchangeTicket=useCallback(async(ticket:string)=>{if(loginBusy.current)return;loginBusy.current=true;setBusy(true);setError('');try{const r=await apiPost('auth.ticket.exchange',{ticket,device_name:Platform.OS==='android'?'Android React Native':'Mobile'},false);await setToken(r.token);await onLoggedIn();}catch(e:any){if(['invalid_ticket','ticket_expired_or_invalid','request_expired_or_invalid'].includes(e.code))setPendingTicket('');setError(e.message||'ورود انجام نشد. دوباره تلاش کنید.');}finally{loginBusy.current=false;setBusy(false)}},[onLoggedIn]);
 useEffect(()=>{const handle=({url}:{url:string})=>{const ticket=loginTicketFromUrl(url);if(!ticket)return;if(consent.current)exchangeTicket(ticket);else setPendingTicket(ticket);};Linking.getInitialURL().then(url=>url&&handle({url}));const sub=Linking.addEventListener('url',handle);return()=>sub.remove();},[exchangeTicket]);
 const openUrl=async(url:string)=>{await Linking.openURL(url)};
 const bale=async()=>{setBusy(true);setError('');try{
   let serverUrl='';
   try{const r=await apiPost('auth.begin',{},false);serverUrl=String(r?.bale_url||'').trim();}catch{}
   if(serverUrl){try{await openUrl(serverUrl);return;}catch{}}
   try{await openUrl('https://ble.ir/picamo_bot?start=APPLOGIN');return;}catch{}
   await openUrl('https://ble.ir/picamo_bot');
 }catch(e:any){setError('امکان باز کردن بله وجود ندارد. لطفاً اتصال اینترنت را بررسی کرده و دوباره تلاش کنید.');}finally{setBusy(false)}};
 const centered={width:'100%' as const,textAlign:'center' as const,writingDirection:'rtl' as const,alignSelf:'stretch' as const};
 return <Screen><StatusBar barStyle="dark-content" backgroundColor={palette.background}/><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingHorizontal:20,paddingTop:32,paddingBottom:32,alignItems:'center'}}>
  <Image source={require('./assets/brand-icon.png')} accessibilityLabel="نشان بازار کسب‌وکار" style={{width:96,height:96,borderRadius:28}} />
  <Txt style={[centered,{fontSize:31,lineHeight:43,fontWeight:'900',marginTop:16}]}>بازار کسب‌وکار</Txt>
  <Txt style={[centered,{color:palette.text2,marginTop:2,fontSize:13.5}]}>اتصال هوشمند  •  رشد پایدار  •  اعتماد واقعی</Txt>
  <SurfaceCard style={{width:'100%',marginTop:24,padding:20,borderRadius:26,alignItems:'center'}}>
   <Txt style={[centered,{fontSize:21,lineHeight:31,fontWeight:'900',marginBottom:8}]}>ورود به حساب</Txt>
   <Txt style={[centered,{color:palette.text2,lineHeight:26,marginBottom:17}]}>با زدن «ورود با بله»، ربات بازار کسب‌وکار باز می‌شود. در بله روی «ورود مستقیم به اپلیکیشن» بزنید.</Txt>
   <Txt style={[centered,{color:palette.text2,fontSize:12.5,lineHeight:22,marginBottom:10}]}>با ورود، شناسه و مشخصات پروفایل بله برای ایجاد و مدیریت حساب شما دریافت می‌شود. پیام‌های پشتیبانی نیز در سامانه ذخیره و برای رسیدگی از طریق ربات بله ارسال می‌شوند.</Txt>
   <View style={{flexDirection:'row-reverse',alignItems:'center',gap:9,minHeight:48,width:'100%',marginBottom:10}}><Pressable accessibilityRole="checkbox" accessibilityLabel="پذیرش حریم خصوصی" accessibilityState={{checked:privacyAccepted}} onPress={()=>{const next=!privacyAccepted;consent.current=next;setPrivacyAccepted(next);}} style={{flex:1,flexDirection:'row-reverse',alignItems:'center',gap:9,minHeight:48}}><AppIcon name={privacyAccepted?'checkbox-marked':'checkbox-blank-outline'} size={25} color={palette.primary}/><Txt style={{flex:1}}>حریم خصوصی را مطالعه کرده‌ام و موافقم.</Txt></Pressable><Pressable accessibilityRole="button" accessibilityLabel="مطالعه حریم خصوصی" hitSlop={6} onPress={()=>setPrivacyOpen(true)}><Txt style={{color:palette.secondary,fontWeight:'800'}}>مطالعه</Txt></Pressable></View>
   <View style={{width:'100%'}}><PrimaryButton title={busy?'در حال ورود…':pendingTicket?'تکمیل ورود':'ورود با بله'} onPress={()=>pendingTicket?exchangeTicket(pendingTicket):bale()} disabled={busy||!privacyAccepted}/></View>
   <Txt style={[centered,{fontSize:12.5,lineHeight:22,color:palette.text2,marginTop:12}]}>اگر ربات را قبلاً شروع نکرده‌اید، ابتدا «شروع» را بزنید؛ سپس گزینه ورود به اپلیکیشن در همان ربات نمایش داده می‌شود.</Txt>
   {error?<View style={{width:'100%',backgroundColor:'#FFF4F2',borderWidth:1,borderColor:'#F2CEC8',borderRadius:15,paddingHorizontal:13,paddingVertical:10,marginTop:14}}><Txt style={[centered,{color:'#A83A32',fontSize:13.5,lineHeight:22,fontWeight:'700'}]}>{error}</Txt></View>:null}
  </SurfaceCard>
  <Txt style={[centered,{color:palette.text2,fontSize:12.5,lineHeight:21,marginTop:13,paddingHorizontal:8}]}>ورود امن است و لینک ورود فقط یک‌بار قابل استفاده است.</Txt>
  <Pressable accessibilityRole="button" onPress={()=>setPrivacyOpen(true)} style={{padding:14,marginTop:8}}><Txt style={[centered,{color:palette.secondary,fontWeight:'700'}]}>حریم خصوصی و دسترسی‌ها</Txt></Pressable>
 </ScrollView><Modal visible={privacyOpen} animationType="slide" onRequestClose={()=>setPrivacyOpen(false)}><Screen><Header title="حریم خصوصی" back onBack={()=>setPrivacyOpen(false)}/><PrivacyScreen/></Screen></Modal></Screen>
}

function Home({boot,navigate}:any){
 const [data,setData]=useState<any>(null);const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const [refreshing,setRefreshing]=useState(false);
 const load=async(refresh=false)=>{refresh?setRefreshing(true):setLoading(true);setErr('');try{setData(await apiGet('home'));}catch(e:any){setErr(e.message)}finally{setLoading(false);setRefreshing(false)}};useEffect(()=>{load()},[]);
 if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={()=>load()}/>;
 const u=boot?.user||{};const st=boot?.stats||{};const name=u.display_name||[u.first_name,u.last_name].filter(Boolean).join(' ')||'کاربر';
 return <ScrollView refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>load(true)} colors={[palette.primary]}/>} contentContainerStyle={s.page}><View style={s.welcome}><View><Txt style={s.hello}>سلام، {name} 👋</Txt><Txt style={s.muted}>کسب‌وکار، مشتری و فرصت‌های بازار را یکجا مدیریت کنید.</Txt></View><View style={s.avatar}><Txt style={{fontSize:22}}>●</Txt></View></View><View style={s.hero}><View style={s.heroBadge}><Txt style={{color:palette.secondary,fontWeight:'900'}}>بازار امروز</Txt></View><Txt style={s.heroTitle}>فرصت‌های کسب‌وکار، نزدیک‌تر از همیشه</Txt><Txt style={s.heroText}>جست‌وجوی هوشمند، دیده‌بان بازار، نوبت‌دهی و کمپین‌ها در یک تجربه یکپارچه.</Txt></View><View style={s.statsRow}><Stat value={st.businesses||0} label="کسب‌وکار"/><Stat value={st.products||0} label="محصول"/><Pressable style={{flex:1}} accessibilityRole="button" accessibilityLabel="مشاهده کسب‌وکارهای دنبال‌شده" onPress={()=>navigate('following')}><Stat value={st.following||0} label="دنبال‌شده"/></Pressable></View>
 {data.admin_test_business?<SurfaceCard style={s.testCard} onPress={()=>navigate('businessDetail',{id:data.admin_test_business.id})}><View style={s.rowBetween}><View style={{flex:1}}><Txt style={s.testTitle}>🧪 فضای تست مدیر</Txt><Txt style={s.muted}>{data.admin_test_business.name}</Txt><Txt style={s.small}>این کسب‌وکار فقط برای مدیر نمایش داده می‌شود.</Txt></View><Txt style={s.arrow}>‹</Txt></View></SurfaceCard>:null}
 <SectionTitle title="دسترسی سریع"/><View style={s.quickGrid}><Quick title="دیده‌بان بازار" icon="↗" onPress={()=>navigate('market')}/><Quick title="نوبت‌های من" icon="◫" onPress={()=>navigate('appointments')}/><Quick title="کمپین‌ها" icon="◉" onPress={()=>navigate('campaigns')}/><Quick title="پلن و فضا" icon="◇" onPress={()=>navigate('plans')}/></View>
 <SectionTitle title="کسب‌وکارهای تازه" more="مشاهده همه" onMore={()=>navigate('search',{mode:'businesses'})}/>{(data.businesses||[]).slice(0,5).map((b:any)=><BusinessCard key={b.id} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>)}
 <SectionTitle title="محصولات تازه"/>{(data.products||[]).slice(0,5).map((p:any)=><ProductCard key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}<View style={{height:24}}/></ScrollView>
}
function Quick({title,icon,onPress}:any){return <Pressable onPress={onPress} style={s.quick}><View style={s.quickIcon}><Txt style={{fontSize:25,color:palette.primary}}>{icon}</Txt></View><Txt style={s.quickText}>{title}</Txt></Pressable>}
function BusinessCard({b,onPress}:any){return <SurfaceCard onPress={onPress}><View style={s.rowBetween}><View style={s.storeIcon}><Txt style={{fontSize:24}}>▣</Txt></View><View style={{flex:1,marginHorizontal:12}}><View style={s.rowR}><Txt style={s.cardTitle}>{b.name}</Txt>{b.is_admin_test?<View style={s.testPill}><Txt style={s.testPillText}>تست مدیر</Txt></View>:null}</View><Txt style={s.muted}>{[b.province,b.city].filter(Boolean).join('، ')||'موقعیت ثبت نشده'}</Txt>{b.description?<Txt numberOfLines={2} style={s.cardDesc}>{b.description}</Txt>:null}</View><Txt style={s.arrow}>‹</Txt></View></SurfaceCard>}
function ProductCard({p,onPress}:any){return <SurfaceCard onPress={onPress}><View style={s.rowBetween}>{p.cover?.url?<Image source={{uri:p.cover.url}} style={s.productThumb}/>:<View style={[s.productThumb,s.thumbPlaceholder]}><Txt style={{fontSize:24}}>□</Txt></View>}<View style={{flex:1,marginHorizontal:12}}><Txt style={s.cardTitle}>{p.name}</Txt><Txt style={s.muted}>{p.business_name||''}</Txt><Txt style={s.price}>{Number(p.price||0)>0?`${money(p.price)} تومان`:'قیمت توافقی'}</Txt></View><Txt style={s.arrow}>‹</Txt></View></SurfaceCard>}

function Search({initial,navigate}:any){
 const [q,setQ]=useState('');const [mode,setMode]=useState(initial?.mode||'all');const [filters,setFilters]=useState<any>({});const [catalog,setCatalog]=useState<any>({provinces:[],cities:[],types:[],categories:[],subcategories:[]});const [data,setData]=useState<any>(null);const [loading,setLoading]=useState(false);const [err,setErr]=useState('');const [picker,setPicker]=useState<any>(null);const [filterOpen,setFilterOpen]=useState(false);
 const loadFilters=async(extra:any={})=>{try{setCatalog(await apiGet('search.filters',extra));}catch(e:any){setErr(e.message)}};useEffect(()=>{loadFilters()},[]);
 const chooseProvince=async(x:any)=>{setFilters((f:any)=>({...f,province:x,city:null}));await loadFilters({province_id:x.id});};
 const chooseCategory=async(x:any)=>{setFilters((f:any)=>({...f,category:x,subcategory:null}));await loadFilters({category_id:x.id});};
 const run=async()=>{setLoading(true);setErr('');try{const p:any={q,mode};if(filters.province)p.province=titleOf(filters.province);if(filters.city)p.city=titleOf(filters.city);if(filters.type)p.type=filters.type.slug||filters.type.name;if(filters.category)p.category_id=filters.category.id;if(filters.subcategory)p.subcategory_id=filters.subcategory.id;if(filters.min)p.min_price=filters.min;if(filters.max)p.max_price=filters.max;setData(await apiGet('search',p));}catch(e:any){setErr(e.message)}finally{setLoading(false)}};
 const pickerData=picker==='province'?catalog.provinces:picker==='city'?catalog.cities:picker==='type'?catalog.types:picker==='category'?catalog.categories:catalog.subcategories;
 const selected=picker==='province'?filters.province:picker==='city'?filters.city:picker==='type'?filters.type:picker==='category'?filters.category:filters.subcategory;
 const onSelect=(x:any)=>{if(picker==='province')chooseProvince(x);else if(picker==='category')chooseCategory(x);else setFilters((f:any)=>({...f,[picker]:x}));};
 return <View style={{flex:1}}><ScrollView contentContainerStyle={s.page} keyboardShouldPersistTaps="handled"><View style={s.searchBox}><Txt style={{fontSize:22,color:palette.primary}}>⌕</Txt><TextInput value={q} onChangeText={setQ} onSubmitEditing={run} placeholder="نام کسب‌وکار یا محصول…" placeholderTextColor={palette.text2} style={s.searchInput}/><Pressable onPress={()=>setFilterOpen(true)} style={s.filterBtn}><Txt style={{color:palette.primary,fontWeight:'900'}}>فیلتر</Txt></Pressable></View><View style={s.chipsRow}><Chip label="همه" active={mode==='all'} onPress={()=>setMode('all')}/><Chip label="کسب‌وکار" active={mode==='businesses'} onPress={()=>setMode('businesses')}/><Chip label="محصول" active={mode==='products'} onPress={()=>setMode('products')}/></View><PrimaryButton title="جست‌وجو" onPress={run}/>{Object.keys(filters).length?<ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.activeFilters}>{['province','city','type','category','subcategory'].map(k=>filters[k]?<Chip key={k} label={titleOf(filters[k])} active/>:null)}{filters.min?<Chip label={`از ${money(filters.min)}`} active/>:null}{filters.max?<Chip label={`تا ${money(filters.max)}`} active/>:null}</ScrollView>:null}{loading?<Loader/>:err?<ErrorState message={err} onRetry={run}/>:data?<><SectionTitle title={`نتایج (${(data.businesses||[]).length+(data.products||[]).length})`}/>{!(data.businesses||[]).length&&!(data.products||[]).length?<EmptyState title="نتیجه‌ای پیدا نشد" detail="فیلترها یا عبارت جست‌وجو را تغییر دهید."/>:null}{(data.businesses||[]).map((b:any)=><BusinessCard key={`b${b.id}`} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>)}{(data.products||[]).map((p:any)=><ProductCard key={`p${p.id}`} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}</>:<View style={s.searchIntro}><Txt style={{fontSize:40}}>⌕</Txt><Txt style={s.searchIntroTitle}>جست‌وجوی دقیق بازار</Txt><Txt style={s.muted}>استان، شهر، نوع فعالیت، دسته و زیردسته و بازه قیمت را هم‌زمان فیلتر کنید.</Txt></View>}</ScrollView><Modal visible={filterOpen} animationType="slide" onRequestClose={()=>setFilterOpen(false)}><Screen><Header title="فیلترهای جست‌وجو" back onBack={()=>setFilterOpen(false)}/><ScrollView contentContainerStyle={s.page}><FilterRow label="استان" value={titleOf(filters.province)||'همه استان‌ها'} onPress={()=>setPicker('province')}/><FilterRow label="شهر" value={titleOf(filters.city)||'همه شهرها'} onPress={()=>setPicker('city')}/><FilterRow label="نوع فعالیت" value={titleOf(filters.type)||'همه انواع'} onPress={()=>setPicker('type')}/><FilterRow label="دسته‌بندی" value={titleOf(filters.category)||'همه دسته‌ها'} onPress={()=>setPicker('category')}/><FilterRow label="زیردسته" value={titleOf(filters.subcategory)||'همه زیردسته‌ها'} onPress={()=>setPicker('subcategory')}/><View style={s.twoCol}><View style={{flex:1}}><Txt style={s.label}>حداقل قیمت</Txt><Field value={filters.min||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,min:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View><View style={{flex:1}}><Txt style={s.label}>حداکثر قیمت</Txt><Field value={filters.max||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,max:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View></View><PrimaryButton title="اعمال فیلتر و جست‌وجو" onPress={()=>{setFilterOpen(false);setTimeout(run,100)}}/><SecondaryButton title="پاک کردن همه فیلترها" onPress={()=>setFilters({})}/></ScrollView></Screen></Modal><SelectSheet visible={!!picker} title={picker==='province'?'انتخاب استان':picker==='city'?'انتخاب شهر':picker==='type'?'نوع فعالیت':picker==='category'?'دسته‌بندی':'زیردسته'} items={pickerData||[]} selectedId={selected?.id||selected?.slug} onClose={()=>setPicker(null)} onSelect={onSelect}/></View>
}
function FilterRow({label,value,onPress}:any){return <Pressable onPress={onPress} style={s.filterRow}><View><Txt style={s.label}>{label}</Txt><Txt style={{fontWeight:'800'}}>{value}</Txt></View><Txt style={s.arrow}>‹</Txt></Pressable>}

function MyBusiness({navigate}:any){const [biz,setBiz]=useState<any[]>([]);const [products,setProducts]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const load=async()=>{setLoading(true);try{const [b,p]=await Promise.all([apiGet('business.mine'),apiGet('product.mine')]);setBiz(b.businesses||[]);setProducts(p.products||[]);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;return <ScrollView contentContainerStyle={s.page}><SectionTitle title="کسب‌وکارهای من"/>{biz.length?biz.map(b=><BusinessCard key={b.id} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>):<EmptyState title="هنوز کسب‌وکاری ندارید"/>}<PrimaryButton title="ثبت کسب‌وکار جدید" onPress={()=>navigate('createBusiness')}/><SectionTitle title="محصولات من"/>{products.map(p=><ProductCard key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}{biz.length?<SecondaryButton title="ثبت محصول جدید" onPress={()=>navigate('createProduct',{businesses:biz})}/>:null}</ScrollView>}

function BusinessDetail({id,navigate}:any){const [d,setD]=useState<any>();const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const load=async()=>{setLoading(true);try{setD(await apiGet('business.detail',{id}));setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[id]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;const b=d.business;return <ScrollView contentContainerStyle={s.page}><View style={s.detailHero}><View style={s.bigStore}><Txt style={{fontSize:40}}>▣</Txt></View><Txt style={s.detailTitle}>{b.name}</Txt>{b.is_admin_test?<View style={s.testPill}><Txt style={s.testPillText}>فقط مدیر • تست</Txt></View>:null}<Txt style={s.muted}>{[b.province,b.city].filter(Boolean).join('، ')}</Txt></View>{b.description?<SurfaceCard><Txt style={s.sectionTitle}>درباره کسب‌وکار</Txt><Txt>{b.description}</Txt></SurfaceCard>:null}<View style={s.twoCol}><PrimaryButton title={d.is_following?'دنبال می‌کنید':'دنبال کردن'} onPress={async()=>{await apiPost('follow.toggle',{business_id:b.id});load()}}/><SecondaryButton title={`${d.followers||0} دنبال‌کننده`} disabled/></View><SectionTitle title="محصولات"/>{(d.products||[]).map((p:any)=><ProductCard key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}{!(d.products||[]).length?<EmptyState title="محصولی ثبت نشده"/>:null}</ScrollView>}

function ProductDetail({id}:any){const {width}=useWindowDimensions();const [d,setD]=useState<any>();const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const [uploading,setUploading]=useState(false);const load=async()=>{setLoading(true);try{setD(await apiGet('product.detail',{id}));setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[id]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;const p=d.product;const media=d.media||[];const pick=async()=>{const r=await launchImageLibrary({mediaType:'mixed',selectionLimit:1});if(r.didCancel||!r.assets?.[0])return;setUploading(true);try{await uploadMedia(id,r.assets[0]);await load()}catch(e:any){setErr(e.message)}finally{setUploading(false)}};return <ScrollView contentContainerStyle={s.page}>{media.length?<ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false} style={{marginHorizontal:-16}}>{media.map((m:any)=>m.type==='video'?<View key={m.id} style={{width:width-0,paddingHorizontal:16}}><Video source={{uri:m.url}} style={s.mediaVideo} controls paused resizeMode="contain"/></View>:<View key={m.id} style={{width:width,paddingHorizontal:16}}><Image source={{uri:m.url}} style={s.mediaImage} resizeMode="cover"/></View>)}</ScrollView>:<View style={s.mediaEmpty}><Txt style={{fontSize:42}}>□</Txt><Txt style={s.muted}>هنوز عکس یا ویدئویی برای این محصول ثبت نشده است.</Txt></View>}<Txt style={s.detailTitle}>{p.name}</Txt><Txt style={s.muted}>{p.business_name||''}</Txt><Txt style={s.bigPrice}>{Number(p.price||0)>0?`${money(p.price)} تومان`:'قیمت توافقی'}</Txt>{p.description?<SurfaceCard><Txt>{p.description}</Txt></SurfaceCard>:null}{d.is_owner?<SurfaceCard><Txt style={s.sectionTitle}>مدیریت رسانه</Txt><Txt style={s.muted}>فضا: {d.quota?.storage_used_mb||0} از {d.quota?.storage_limit_mb||0} مگابایت • عکس {d.quota?.photo_limit_per_product??'-'} • ویدئو {d.quota?.video_limit_per_product??'-'}</Txt><PrimaryButton title={uploading?'در حال بارگذاری…':'افزودن عکس یا ویدئو'} onPress={pick} disabled={uploading}/></SurfaceCard>:null}</ScrollView>}

function Support(){const [d,setD]=useState<any>({messages:[]});const [body,setBody]=useState('');const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const load=async()=>{try{setD(await apiGet('support.mine'));setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load();const t=setInterval(load,12000);return()=>clearInterval(t)},[]);const send=async()=>{if(!body.trim())return;try{await apiPost('support.send',{body:body.trim()});setBody('');await load()}catch(e:any){setErr(e.message)}};if(loading)return <Loader/>;return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView contentContainerStyle={s.page}>{err?<Txt style={s.errorText}>{err}</Txt>:null}{!d.request?<SurfaceCard><Txt style={s.sectionTitle}>پشتیبانی بازار کسب‌وکار</Txt><Txt style={s.muted}>پیام شما برای پشتیبان و مدیر سامانه ارسال می‌شود.</Txt></SurfaceCard>:<Txt style={s.muted}>گفتگو #{d.request.thread_id} • {d.request.status}</Txt>}{(d.messages||[]).map((m:any)=><View key={m.id} style={[s.bubble,m.sender_role==='user'?s.mine:s.theirs]}><Txt>{m.body}</Txt><Txt style={s.time}>{m.created_at}</Txt></View>)}</ScrollView><View style={s.composer}><TextInput value={body} onChangeText={setBody} placeholder="پیام شما…" placeholderTextColor={palette.text2} multiline style={s.composerInput}/><Pressable onPress={send} style={s.send}><Txt style={{color:'#fff',fontSize:20}}>›</Txt></Pressable></View></KeyboardAvoidingView>}

function Account({boot,setBoot,navigate,onLogout}:any){const u=boot?.user||{};const prefs=boot?.preferences||{};const toggle=async(kind:string,val:boolean)=>{await apiPost('preferences.update',{kind,enabled:val});const b=await apiGet('bootstrap');setBoot(b)};return <ScrollView contentContainerStyle={s.page}><SurfaceCard><View style={s.profile}><View style={s.profileAvatar}><Txt style={{fontSize:28}}>●</Txt></View><View style={{flex:1}}><Txt style={s.cardTitle}>{u.display_name||`${u.first_name||''} ${u.last_name||''}`.trim()||'کاربر'}</Txt><Txt style={s.muted}>{u.username?`@${u.username}`:`شناسه بله: ${u.bale_user_id||'-'}`}</Txt>{u.is_admin?<View style={s.adminPill}><Txt style={s.adminText}>مدیر سامانه</Txt></View>:null}{u.is_test_user?<View style={s.testPill}><Txt style={s.testPillText}>کاربر آزمایشی</Txt></View>:null}</View></View></SurfaceCard><MenuRow title="پلن، اشتراک و فضای رسانه" icon="◇" onPress={()=>navigate('plans')}/><MenuRow title="نوبت‌های من" icon="◫" onPress={()=>navigate('appointments')}/><MenuRow title="کمپین‌ها" icon="◉" onPress={()=>navigate('campaigns')}/><MenuRow title="علاقه‌مندی‌ها" icon="♡" onPress={()=>navigate('favorites')}/>{u.is_admin?<MenuRow title="ورود با کاربر آزمایشی" icon="🧪" onPress={async()=>{const r=await apiPost('admin.test_user.login',{});await setToken(r.token);const b=await apiGet('bootstrap');setBoot(b)}}/>:null}<SurfaceCard><ToggleRow title="دیده‌بان بازار" value={!!prefs.market_watch} onPress={()=>toggle('market_watch',!prefs.market_watch)}/>{prefs.daily_tip!==null&&prefs.daily_tip!==undefined?<ToggleRow title="نکته روزانه کسب‌وکار" value={!!prefs.daily_tip} onPress={()=>toggle('daily_tip',!prefs.daily_tip)}/>:null}</SurfaceCard><SecondaryButton title="خروج از حساب" onPress={onLogout}/></ScrollView>}
function MenuRow({title,icon,onPress}:any){return <SurfaceCard onPress={onPress}><View style={s.rowBetween}><View style={s.rowR}><View style={s.menuIcon}><Txt style={{fontSize:21}}>{icon}</Txt></View><Txt style={{fontWeight:'800',fontSize:16}}>{title}</Txt></View><Txt style={s.arrow}>‹</Txt></View></SurfaceCard>}
function ToggleRow({title,value,onPress}:any){return <Pressable onPress={onPress} style={s.toggleRow}><Txt style={{fontWeight:'800'}}>{title}</Txt><View style={[s.toggle,value&&s.toggleOn]}><View style={[s.knob,value&&s.knobOn]}/></View></Pressable>}

function GenericList({action,keyName,title}:any){const [d,setD]=useState<any>();const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const load=async()=>{try{setD(await apiGet(action));setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;const rows=d?.[keyName]||[];return <ScrollView contentContainerStyle={s.page}>{!rows.length?<EmptyState title="موردی وجود ندارد"/>:rows.map((x:any,i:number)=><SurfaceCard key={x.id||i}><Txt style={s.cardTitle}>{x.title||x.business_name||x.name||x.service_name||`مورد ${i+1}`}</Txt><Txt style={s.muted}>{x.description||x.reward_text||x.status||x.appointment_date||''}</Txt></SurfaceCard>)}</ScrollView>}

function CreateBusiness({onDone}:any){const [f,setF]=useState<any>({name:'',manager_name:'',phone:'',province:'',city:'',address:'',description:''});const [busy,setBusy]=useState(false);const [err,setErr]=useState('');const submit=async()=>{setBusy(true);try{await apiPost('business.create',f);onDone()}catch(e:any){setErr(e.message)}finally{setBusy(false)}};return <ScrollView contentContainerStyle={s.page}>{[['name','نام کسب‌وکار'],['manager_name','نام مدیر'],['phone','شماره تماس'],['province','استان'],['city','شهر'],['address','آدرس']].map(([k,l])=><View key={k}><Txt style={s.label}>{l}</Txt><Field value={f[k]} onChangeText={(v:string)=>setF({...f,[k]:v})} placeholder={l}/></View>)}<Txt style={s.label}>توضیحات</Txt><Field value={f.description} onChangeText={(v:string)=>setF({...f,description:v})} placeholder="معرفی کوتاه" multiline/>{err?<Txt style={s.errorText}>{err}</Txt>:null}<PrimaryButton title={busy?'در حال ثبت…':'ثبت کسب‌وکار'} onPress={submit} disabled={busy}/></ScrollView>}
function CreateProduct(props:any){return <ProductFormScreen {...props}/>;}

function AppRoot(){
 const [bootError,setBootError]=useState('');const [ready,setReady]=useState(false);const [logged,setLogged]=useState(false);const [boot,setBoot]=useState<any>();const [tab,setTab]=useState<TabKey>('home');const [stack,setStack]=useState<Route[]>([]);
 const refreshBoot=useCallback(async()=>{try{const t=await getToken();if(!t){setLogged(false);setBoot(null);return}const b=await apiGet('bootstrap');setBoot(b);setBootError('');setLogged(true)}catch(e:any){if(e.status!==401){setBootError(e.message||'ارتباط با سرور برقرار نشد.');return}await clearToken();Object.assign(mobileCacheV5,{home:null,mine:null,support:null,businessDetail:{},productDetail:{}});setLogged(false);setBoot(null)}finally{setReady(true)}},[]);
 useEffect(()=>{refreshBoot()},[refreshBoot]);
 const route=stack[stack.length-1];const navigate=(name:string,params?:any)=>setStack(x=>[...x,{name,params}]);const back=useCallback(()=>setStack(x=>x.slice(0,-1)),[]);
 useEffect(()=>{const h=BackHandler.addEventListener('hardwareBackPress',()=>{if(stack.length){back();return true}if(tab!=='home'){setTab('home');return true}return false});return()=>h.remove()},[stack.length,tab]);
 if(!ready)return <Screen><Loader/></Screen>;if(bootError)return <Screen><ErrorState message={bootError} onRetry={refreshBoot}/></Screen>;if(!logged)return <Login onLoggedIn={refreshBoot}/>;
 const logout=async()=>{try{await apiPost('logout')}catch{}await clearToken();Object.assign(mobileCacheV5,{home:null,mine:null,support:null,businessDetail:{},productDetail:{}});setLogged(false);setBoot(null);setStack([])};
 const detail=()=>{if(!route)return null;const common={back:true,onBack:back};switch(route.name){case'commercialPage':return <><Header {...common} title="فرصت‌های تجاری"/><CommercialOpportunitiesScreen onOpenBusiness={(id:number)=>navigate('businessDetail',{id})}/></>;case'privacy':return <><Header {...common} title="حریم خصوصی"/><PrivacyScreen/></>;case'chatThread':return <MarketplaceThread key={route.params.threadId||'business-'+route.params.businessId} businessId={route.params.businessId} threadId={route.params.threadId} onBack={back}/>;case'businessDetail':return <BusinessDetailV6 id={route.params.id} navigate={navigate} onBack={back} onFollowChanged={refreshBoot}/>;case'productDetail':return <ProductDetailV6 id={route.params.id} navigate={navigate} onBack={back}/>;case'plans':return <><Header {...common} title="پلن و فضای رسانه"/><PlansScreen/></>;case'appointments':return <><Header {...common} title="نوبت‌های من"/><GenericList action="appointments.mine" keyName="appointments"/></>;case'campaigns':return <><Header {...common} title="کمپین‌ها"/><GenericList action="campaigns.active" keyName="campaigns"/></>;case'favorites':case'following':return <><Header {...common} title="کسب‌وکارهای دنبال‌شده"/><BusinessNetworkScreen navigate={navigate}/></>;case'followers':return <><Header {...common} title="دنبال‌کننده‌های کسب‌وکار"/><BusinessNetworkScreen key={route.params.id} businessId={route.params.id} navigate={navigate}/></>;case'myBusiness':return <><Header {...common} title="کسب‌وکارهای من"/><MyBusinessV5 navigate={navigate} mode="businesses"/></>;case'myProducts':return <><Header {...common} title="محصولات من"/><MyBusinessV5 navigate={navigate} mode="products"/></>;case'market':return <><Header {...common} title="دیده‌بان بازار"/><GenericList action="market.latest" keyName="rates"/></>;case'createBusiness':return <><Header {...common} title="ثبت کسب‌وکار"/><BusinessFormScreen onDone={()=>{mobileCacheV5.mine=null;mobileCacheV5.home=null;back();}}/></>;case'editBusiness':return <><Header {...common} title="ویرایش کسب‌وکار"/><EditBusinessV7 id={route.params.id} onDone={()=>{mobileCacheV5.mine=null;mobileCacheV5.home=null;delete mobileCacheV5.businessDetail[route.params.id];back();}}/></>;case'createProduct':return <><Header {...common} title="ثبت محصول"/><CreateProduct businesses={route.params.businesses} onDone={()=>back()}/></>;case'adminDashboard':return <><Header {...common} title="مدیریت سامانه"/><AdminHub navigate={navigate}/></>;case'adminPanel':return <AdminPanelScreen onBack={back}/>;case'adminDelivery':return <><Header {...common} title="وضعیت ارسال به بله"/><AdminDeliveryScreen/></>;case'adminSupportThread':return <><Header {...common} title={`پشتیبانی #${route.params.threadId}`}/><SupportScreen adminThreadId={route.params.threadId}/></>;case'searchPage':return <><Header {...common} title="جست‌وجو"/><SearchV5 initial={route.params||{}} navigate={navigate} boot={boot}/></>;case'supportPage':return <><Header {...common} title="پشتیبانی"/><SupportScreen/></>;default:return null}}
 const tabView=tab==='home'?<HomeV5 boot={boot} navigate={navigate} setBoot={setBoot}/>:tab==='search'?<SearchV5 navigate={navigate} boot={boot}/>:tab==='business'?<MyBusinessV5 navigate={navigate}/>:tab==='messages'?<MarketplaceInbox navigate={navigate}/>:<AccountV5 boot={boot} setBoot={setBoot} navigate={navigate} onLogout={logout}/>;
 return <Screen><StatusBar barStyle="dark-content" backgroundColor={palette.background}/><View style={{flex:1}}>{route?detail():tabView}</View><BottomNav active={route?.name==='chatThread'?'messages':tab} onChange={k=>{setStack([]);setTab(k)}}/></Screen>
}
export default function App(){return <SafeAreaProvider><PaperProvider theme={theme as any}><AppRoot/></PaperProvider></SafeAreaProvider>}

