function CreateBusinessV2({onDone}:any){
 const [f,setF]=useState<any>({name:'',manager_name:'',phone:'',address:'',description:'',province:null,city:null,type:null,category:null});
 const [catalog,setCatalog]=useState<any>({provinces:[],cities:[],types:[],categories:[]});
 const [picker,setPicker]=useState<string|null>(null);const [busy,setBusy]=useState(false);const [err,setErr]=useState('');
 const loadFilters=async(extra:any={})=>{try{const x=await apiGet('search.filters',extra);setCatalog((c:any)=>({...c,...x}));}catch(e:any){setErr(e.message)}};
 useEffect(()=>{loadFilters()},[]);
 const select=async(x:any)=>{if(picker==='province'){setF((v:any)=>({...v,province:x,city:null}));await loadFilters({province_id:x.id});}else setF((v:any)=>({...v,[picker as string]:x}));setPicker(null)};
 const submit=async()=>{if(!f.province||!f.city){setErr('استان و شهر را انتخاب کنید.');return}setBusy(true);setErr('');try{await apiPost('business.create',{name:f.name,manager_name:f.manager_name,phone:f.phone,province:titleOf(f.province),city:titleOf(f.city),address:f.address,description:f.description,type_slugs:f.type?.slug?[f.type.slug]:[],category_ids:f.category?.id?[f.category.id]:[]});onDone()}catch(e:any){setErr(e.message)}finally{setBusy(false)}};
 const items=picker==='province'?catalog.provinces:picker==='city'?catalog.cities:picker==='type'?catalog.types:catalog.categories;
 const selected=picker==='province'?f.province:picker==='city'?f.city:picker==='type'?f.type:f.category;
 return <ScrollView contentContainerStyle={s.page} keyboardShouldPersistTaps="handled"><Txt style={s.label}>نام کسب‌وکار</Txt><Field value={f.name} onChangeText={(v:string)=>setF({...f,name:v})} placeholder="نام کسب‌وکار"/><Txt style={s.label}>نام مدیر</Txt><Field value={f.manager_name} onChangeText={(v:string)=>setF({...f,manager_name:v})} placeholder="نام مدیر"/><Txt style={s.label}>شماره تماس</Txt><Field value={f.phone} onChangeText={(v:string)=>setF({...f,phone:v})} placeholder="شماره تماس" keyboardType="phone-pad"/><Txt style={s.label}>استان</Txt><FilterRow label="" value={titleOf(f.province)||'انتخاب استان'} onPress={()=>setPicker('province')}/><Txt style={s.label}>شهر</Txt><FilterRow label="" value={titleOf(f.city)||'انتخاب شهر'} onPress={()=>{if(!f.province){setErr('ابتدا استان را انتخاب کنید.');return}setPicker('city')}}/><Txt style={s.label}>نوع فعالیت</Txt><FilterRow label="" value={titleOf(f.type)||'انتخاب نوع فعالیت'} onPress={()=>setPicker('type')}/><Txt style={s.label}>دسته‌بندی</Txt><FilterRow label="" value={titleOf(f.category)||'انتخاب دسته‌بندی'} onPress={()=>setPicker('category')}/><Txt style={s.label}>آدرس</Txt><Field value={f.address} onChangeText={(v:string)=>setF({...f,address:v})} placeholder="آدرس"/><Txt style={s.label}>توضیحات</Txt><Field value={f.description} onChangeText={(v:string)=>setF({...f,description:v})} placeholder="معرفی کوتاه" multiline/>{err?<Txt style={s.errorText}>{err}</Txt>:null}<PrimaryButton title={busy?'در حال ثبت…':'ثبت کسب‌وکار'} onPress={submit} disabled={busy}/><SelectSheet visible={!!picker} title={picker==='province'?'انتخاب استان':picker==='city'?'انتخاب شهر':picker==='type'?'انتخاب نوع فعالیت':'انتخاب دسته‌بندی'} items={items||[]} selectedId={selected?.id||selected?.slug} onClose={()=>setPicker(null)} onSelect={select}/></ScrollView>
}

function HomeV2({boot,navigate}:any){return <View style={{flex:1}}><Home boot={boot} navigate={navigate}/>{boot?.user?.is_admin?<Pressable onPress={()=>navigate('adminDashboard')} style={{position:'absolute',left:16,bottom:18,backgroundColor:palette.secondary,paddingHorizontal:17,paddingVertical:12,borderRadius:18,elevation:6}}><Txt style={{color:'#fff',fontWeight:'900'}}>مدیریت سامانه</Txt></Pressable>:null}</View>}

function AdminDashboard({navigate}:any){
 const [d,setD]=useState<any>();const [tickets,setTickets]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [err,setErr]=useState('');
 const load=async()=>{setLoading(true);setErr('');try{const [x,t]=await Promise.all([apiGet('admin.dashboard'),apiGet('admin.support.list')]);setD(x);setTickets(t.requests||[])}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);
 if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;const st=d?.stats||{};
 return <ScrollView contentContainerStyle={s.page} refreshControl={<RefreshControl refreshing={false} onRefresh={load} colors={[palette.primary]}/>}><View style={s.hero}><Txt style={s.heroBadge}>مدیریت</Txt><Txt style={s.heroTitle}>داشبورد بازار کسب‌وکار</Txt><Txt style={s.heroText}>نمای مدیریتی کاربران، کسب‌وکارها، محصولات و پشتیبانی.</Txt></View><View style={s.statsRow}><Stat value={st.users||0} label="کاربر"/><Stat value={st.businesses||0} label="کسب‌وکار"/><Stat value={st.products||0} label="محصول"/></View><View style={s.statsRow}><Stat value={st.business_pending||0} label="کسب‌وکار معلق"/><Stat value={st.product_pending||0} label="محصول معلق"/><Stat value={st.reports_open||0} label="گزارش باز"/></View><SectionTitle title={`تیکت‌های پشتیبانی (${tickets.length})`}/>{tickets.length?tickets.map((x:any)=><SurfaceCard key={x.thread_id||x.id} onPress={()=>navigate('adminSupportThread',{threadId:x.thread_id})}><View style={s.rowBetween}><View style={{flex:1}}><Txt style={s.cardTitle}>{x.requester_name||x.display_name||`گفتگو #${x.thread_id}`}</Txt><Txt style={s.muted}>{x.last_message||x.subject||x.status||'در انتظار بررسی'}</Txt></View><Txt style={s.arrow}>‹</Txt></View></SurfaceCard>):<EmptyState title="تیکت بازی وجود ندارد"/>}</ScrollView>
}

function AdminSupportThread({threadId}:any){
 const [messages,setMessages]=useState<any[]>([]);const [body,setBody]=useState('');const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const [sending,setSending]=useState(false);
 const load=async()=>{try{const r=await apiGet('admin.support.messages',{thread_id:threadId});setMessages(r.messages||[]);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[threadId]);
 const send=async()=>{if(!body.trim())return;setSending(true);try{await apiPost('admin.support.reply',{thread_id:threadId,body:body.trim()});setBody('');await load()}catch(e:any){setErr(e.message)}finally{setSending(false)}};
 if(loading)return <Loader/>;return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView contentContainerStyle={s.page}>{err?<Txt style={s.errorText}>{err}</Txt>:null}{messages.map((m:any)=><View key={m.id} style={[s.bubble,m.sender_role==='admin'?s.mine:s.theirs]}><Txt>{m.body}</Txt><Txt style={s.time}>{m.created_at}</Txt></View>)}</ScrollView><View style={s.composer}><TextInput value={body} onChangeText={setBody} placeholder="پاسخ مدیر…" placeholderTextColor={palette.text2} multiline style={s.composerInput}/><Pressable disabled={sending} onPress={send} style={[s.send,sending&&{opacity:.5}]}><Txt style={{color:'#fff',fontSize:20}}>›</Txt></Pressable></View></KeyboardAvoidingView>
}

