function SearchFilterButton({label,value,onPress,disabled=false}:any){return <Pressable disabled={disabled} onPress={onPress} style={{flex:1,minHeight:58,borderRadius:17,backgroundColor:disabled?palette.surface2:'#fff',borderWidth:1,borderColor:palette.border,paddingHorizontal:11,paddingVertical:8,justifyContent:'center',opacity:disabled ? .55 : 1}}><Txt style={{fontSize:11.5,color:palette.text2,textAlign:'right'}}>{label}</Txt><View style={{flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between'}}><Txt numberOfLines={1} style={{flex:1,fontSize:13.5,fontWeight:'800',textAlign:'right'}}>{value}</Txt><AppIcon name="chevron-down" size={18} color={palette.text2}/></View></Pressable>}

function SearchV4({initial,navigate,boot}:any){
 const [q,setQ]=useState('');const [mode,setMode]=useState(initial?.mode||'all');const [filters,setFilters]=useState<any>({});const [catalog,setCatalog]=useState<any>({provinces:[],cities:[],types:[],categories:[],subcategories:[]});const [data,setData]=useState<any>(null);const [loading,setLoading]=useState(false);const [err,setErr]=useState('');const [picker,setPicker]=useState<any>(null);const [more,setMore]=useState(false);
 const applyCatalog=async(extra:any={})=>{const x=await apiGet('search.filters',extra);setCatalog((c:any)=>({...c,...x}));return x};
 useEffect(()=>{(async()=>{try{const x=await applyCatalog();const up=String(boot?.user?.province||'').trim();const uc=String(boot?.user?.city||'').trim();if(up){const p=(x.provinces||[]).find((z:any)=>titleOf(z)===up);if(p){const y=await applyCatalog({province_id:p.id});const c=(y.cities||[]).find((z:any)=>titleOf(z)===uc);setFilters((f:any)=>({...f,province:p,city:c||null}));}}}catch(e:any){setErr(e.message)}})()},[]);
 const chooseProvince=async(x:any)=>{setFilters((f:any)=>({...f,province:x,city:null}));try{await applyCatalog({province_id:x.id})}catch(e:any){setErr(e.message)}};
 const chooseCategory=async(x:any)=>{setFilters((f:any)=>({...f,category:x,subcategory:null}));try{await applyCatalog({category_id:x.id})}catch(e:any){setErr(e.message)}};
 const onSelect=(x:any)=>{if(picker==='province')chooseProvince(x);else if(picker==='category')chooseCategory(x);else setFilters((f:any)=>({...f,[picker]:x}));setPicker(null)};
 const pickerData=picker==='province'?catalog.provinces:picker==='city'?catalog.cities:picker==='type'?catalog.types:picker==='category'?catalog.categories:catalog.subcategories;
 const selected=picker==='province'?filters.province:picker==='city'?filters.city:picker==='type'?filters.type:picker==='category'?filters.category:filters.subcategory;
 const run=async()=>{setLoading(true);setErr('');try{const p:any={q,mode};if(filters.province)p.province=titleOf(filters.province);if(filters.city)p.city=titleOf(filters.city);if(filters.type)p.type=filters.type.slug||filters.type.name;if(filters.category)p.category_id=filters.category.id;if(filters.subcategory)p.subcategory_id=filters.subcategory.id;if(filters.min)p.min_price=filters.min;if(filters.max)p.max_price=filters.max;setData(await apiGet('search',p));}catch(e:any){setErr(e.message)}finally{setLoading(false)}};
 const clear=()=>{setFilters({});setData(null);setErr('');setMore(false);applyCatalog().catch(()=>{})};
 return <View style={{flex:1}}><ScrollView contentContainerStyle={{padding:14,paddingBottom:28}} keyboardShouldPersistTaps="handled">
  <View style={{minHeight:54,borderRadius:18,backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,flexDirection:'row',alignItems:'center',paddingHorizontal:12,marginBottom:10}}><AppIcon name="magnify" size={23} color={palette.primary}/><TextInput value={q} onChangeText={setQ} onSubmitEditing={run} placeholder="نام کسب‌وکار یا محصول…" placeholderTextColor={palette.text2} style={{flex:1,height:52,textAlign:'right',writingDirection:'rtl',fontSize:14.5,color:palette.text,paddingHorizontal:9}}/></View>
  <View style={{flexDirection:'row-reverse',gap:7,marginBottom:10}}><Chip label="همه" active={mode==='all'} onPress={()=>setMode('all')}/><Chip label="کسب‌وکار" active={mode==='businesses'} onPress={()=>setMode('businesses')}/><Chip label="محصول" active={mode==='products'} onPress={()=>setMode('products')}/></View>
  <Txt style={{fontSize:13,fontWeight:'800',color:palette.text2,marginBottom:7,textAlign:'right'}}>فیلترهای اصلی</Txt>
  <View style={{flexDirection:'row',gap:8,marginBottom:8}}><SearchFilterButton label="استان" value={titleOf(filters.province)||'همه استان‌ها'} onPress={()=>setPicker('province')}/><SearchFilterButton label="شهر" value={titleOf(filters.city)||'همه شهرها'} disabled={!filters.province} onPress={()=>setPicker('city')}/></View>
  <View style={{flexDirection:'row',gap:8,marginBottom:8}}><SearchFilterButton label="نوع فعالیت" value={titleOf(filters.type)||'همه انواع'} onPress={()=>setPicker('type')}/><SearchFilterButton label="دسته‌بندی" value={titleOf(filters.category)||'همه دسته‌ها'} onPress={()=>setPicker('category')}/></View>
  <Pressable onPress={()=>setMore(v=>!v)} style={{minHeight:42,borderRadius:14,backgroundColor:palette.surface2,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:6,marginBottom:9}}><AppIcon name={more?'chevron-up':'tune-variant'} size={19} color={palette.primary}/><Txt style={{fontSize:13.5,color:palette.primary,fontWeight:'800',textAlign:'center'}}>{more?'بستن فیلترهای بیشتر':'فیلترهای بیشتر: زیردسته و قیمت'}</Txt></Pressable>
  {more?<View style={{marginBottom:9}}><SearchFilterButton label="زیردسته" value={titleOf(filters.subcategory)||'همه زیردسته‌ها'} disabled={!filters.category} onPress={()=>setPicker('subcategory')}/><View style={{flexDirection:'row',gap:8,marginTop:8}}><View style={{flex:1}}><Txt style={{fontSize:11.5,color:palette.text2,marginBottom:4}}>حداقل قیمت</Txt><Field value={filters.min||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,min:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View><View style={{flex:1}}><Txt style={{fontSize:11.5,color:palette.text2,marginBottom:4}}>حداکثر قیمت</Txt><Field value={filters.max||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,max:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View></View></View>:null}
  <PrimaryButton title={loading?'در حال جست‌وجو…':'جست‌وجو'} icon="magnify" onPress={run} disabled={loading}/>
  {Object.keys(filters).length?<Pressable onPress={clear} style={{alignSelf:'center',padding:9}}><Txt style={{fontSize:12.5,color:palette.text2,textAlign:'center'}}>پاک کردن فیلترها</Txt></Pressable>:null}
  {err?<ErrorState message={err} onRetry={run}/>:null}
  {data?<><View style={{flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between',marginTop:12,marginBottom:8}}><Txt style={{fontSize:16.5,fontWeight:'900'}}>نتایج</Txt><Txt style={{fontSize:12.5,color:palette.text2}}>{(data.businesses||[]).length+(data.products||[]).length} مورد</Txt></View>{!(data.businesses||[]).length&&!(data.products||[]).length?<EmptyState title="نتیجه‌ای پیدا نشد" detail="عبارت یا فیلترها را تغییر دهید."/>:null}{(data.businesses||[]).map((b:any)=><ModernBusinessCard key={`b${b.id}`} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>)}{(data.products||[]).map((p:any)=><ModernProductCard key={`p${p.id}`} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}</>:<View style={{minHeight:180,alignItems:'center',justifyContent:'center',paddingHorizontal:25}}><AppIcon name="map-search-outline" size={42} color={palette.primary}/><Txt style={{fontSize:16,fontWeight:'900',marginTop:7,textAlign:'center'}}>جست‌وجوی دقیق بازار</Txt><Txt style={{fontSize:12.5,color:palette.text2,textAlign:'center',marginTop:4}}>استان، شهر، نوع فعالیت و دسته را همین‌جا انتخاب کنید.</Txt></View>}
 </ScrollView><SelectSheet visible={!!picker} title={picker==='province'?'انتخاب استان':picker==='city'?'انتخاب شهر':picker==='type'?'نوع فعالیت':picker==='category'?'دسته‌بندی':'زیردسته'} items={pickerData||[]} selectedId={selected?.id||selected?.slug} onClose={()=>setPicker(null)} onSelect={onSelect}/></View>
}

