  <View style={{flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between',marginTop:4,marginBottom:8}}><Txt style={{fontSize:17,fontWeight:'900'}}>محصولات</Txt><Txt style={{fontSize:12.5,color:palette.text2}}>{(d.products||[]).length} مورد</Txt></View>
