function ProductDetailV4({id,navigate}:any){
 const {width}=useWindowDimensions();const [d,setD]=useState<any>();const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const [uploading,setUploading]=useState(false);
 const load=async()=>{setLoading(true);setErr('');try{setD(await apiGet('product.detail',{id}))}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[id]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;const p=d.product;const media=d.media||[];
 const contact=()=>navigate('chatThread',{businessId:p.business_id});
 const pick=async()=>{const r=await launchImageLibrary({mediaType:'mixed',selectionLimit:1});if(r.didCancel||!r.assets?.[0])return;setUploading(true);try{await uploadMedia(id,r.assets[0]);await load()}catch(e:any){setErr(e.message)}finally{setUploading(false)}};
 return <ScrollView contentContainerStyle={{padding:14,paddingBottom:30}}>{media.length?<ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false} style={{marginHorizontal:-14,marginBottom:13}}>{media.map((m:any)=>m.type==='video'?<View key={m.id} style={{width,paddingHorizontal:14}}><Video source={{uri:m.url}} style={{height:300,borderRadius:22,backgroundColor:'#101614'}} controls paused resizeMode="contain"/></View>:<View key={m.id} style={{width,paddingHorizontal:14}}><Image source={{uri:m.url}} style={{height:300,borderRadius:22,backgroundColor:palette.border}} resizeMode="cover"/></View>)}</ScrollView>:<View style={{height:220,borderRadius:22,backgroundColor:palette.surface2,alignItems:'center',justifyContent:'center',marginBottom:12}}><AppIcon name="image-outline" size={45} color={palette.text2}/></View>}
  <Txt style={{fontSize:20,fontWeight:'900',textAlign:'right',width:'100%'}}>{p.name}</Txt><Pressable onPress={()=>navigate('businessDetail',{id:p.business_id})}><Txt style={{fontSize:13,color:palette.text2,textAlign:'right',width:'100%',marginTop:2}}>{p.business_name||''}</Txt></Pressable><Txt style={{fontSize:20,color:palette.primary,fontWeight:'900',textAlign:'right',width:'100%',marginVertical:9}}>{Number(p.price||0)>0?`${money(p.price)} تومان`:'قیمت توافقی'}</Txt>
  {p.description?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,padding:14,marginBottom:10}}><Txt style={{fontSize:13.5,lineHeight:23,textAlign:'right'}}>{p.description}</Txt></View>:null}
  {!d.is_owner?<PrimaryButton title="گفتگوی رایگان در اپلیکیشن" icon="message-text-outline" onPress={contact}/>:null}
  {d.is_owner?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,padding:14,marginTop:10}}><Txt style={{fontSize:16,fontWeight:'900',marginBottom:4}}>مدیریت رسانه</Txt><Txt style={{fontSize:12.5,color:palette.text2,marginBottom:9}}>فضا: {d.quota?.storage_used_mb||0} از {d.quota?.storage_limit_mb||0} مگابایت</Txt><PrimaryButton title={uploading?'در حال بارگذاری…':'افزودن عکس یا ویدئو'} icon="image-plus" onPress={pick} disabled={uploading}/></View>:null}
 </ScrollView>
}

function MyBusinessV4({navigate}:any){const [biz,setBiz]=useState<any[]>([]);const [products,setProducts]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [err,setErr]=useState('');const load=async()=>{setLoading(true);try{const [b,p]=await Promise.all([apiGet('business.mine'),apiGet('product.mine')]);setBiz(b.businesses||[]);setProducts(p.products||[]);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);if(loading)return <Loader/>;if(err)return <ErrorState message={err} onRetry={load}/>;return <ScrollView contentContainerStyle={{padding:14,paddingBottom:28}}><View style={{flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between',marginBottom:8}}><Txt style={{fontSize:17,fontWeight:'900',textAlign:'right',width:'100%'}}>کسب‌وکارهای من</Txt><Pressable onPress={()=>navigate('createBusiness')} style={{width:38,height:38,borderRadius:13,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="plus" size={22} color={palette.primary}/></Pressable></View>{biz.length?biz.map(b=><ModernBusinessCard key={b.id} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>):<EmptyState title="هنوز کسب‌وکاری ندارید" detail="برای شروع، کسب‌وکار خود را ثبت کنید."/>}{biz.length?<><View style={{flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between',marginTop:10,marginBottom:8}}><Txt style={{fontSize:17,fontWeight:'900',textAlign:'right',width:'100%'}}>محصولات من</Txt><Pressable onPress={()=>navigate('createProduct',{businesses:biz})} style={{width:38,height:38,borderRadius:13,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="plus" size={22} color={palette.primary}/></Pressable></View>{products.map(p=><ModernProductCard key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}</>:null}</ScrollView>}

