function FilterBtnV5({label,value,onPress,disabled=false}:any){return <Pressable disabled={disabled} onPress={onPress} style={{flex:1,minHeight:58,borderRadius:16,backgroundColor:disabled?palette.surface2:'#fff',borderWidth:1,borderColor:palette.border,paddingHorizontal:11,paddingVertical:8,justifyContent:'center',opacity:disabled ? .55 : 1}}><Txt style={{fontSize:11,color:palette.text2,textAlign:'right',width:'100%'}}>{label}</Txt><View style={{position:'relative',paddingLeft:22}}><Txt numberOfLines={1} style={{fontSize:13,fontWeight:'800',textAlign:'right',width:'100%'}}>{value}</Txt><View style={{position:'absolute',left:0,top:0}}><AppIcon name="chevron-down" size={18} color={palette.text2}/></View></View></Pressable>}

function SearchV5({initial,navigate,boot}:any){
 const [q,setQ]=useState('');const [mode,setMode]=useState(initial?.mode||'all');const [filters,setFilters]=useState<any>({});const [catalog,setCatalog]=useState<any>(mobileCacheV5.searchCatalog||{provinces:[],cities:[],types:[],categories:[],subcategories:[]});const [data,setData]=useState<any>(null);const [loading,setLoading]=useState(false);const [err,setErr]=useState('');const [picker,setPicker]=useState<any>(null);const [more,setMore]=useState(false);
 const applyCatalog=async(extra:any={})=>{const x=await apiGet('search.filters',extra);const merged={...mobileCacheV5.searchCatalog,...x};mobileCacheV5.searchCatalog=merged;setCatalog(merged);return x};
 useEffect(()=>{if(mobileCacheV5.searchCatalog)return;(async()=>{try{await applyCatalog()}catch(e:any){setErr(e.message)}})()},[]);
 const chooseProvince=async(x:any)=>{setFilters((f:any)=>({...f,province:x,city:null}));try{await applyCatalog({province_id:x.id})}catch(e:any){setErr(e.message)}};const chooseCategory=async(x:any)=>{setFilters((f:any)=>({...f,category:x,subcategory:null}));try{await applyCatalog({category_id:x.id})}catch(e:any){setErr(e.message)}};
 const onSelect=(x:any)=>{if(picker==='province')chooseProvince(x);else if(picker==='category')chooseCategory(x);else setFilters((f:any)=>({...f,[picker]:x}));setPicker(null)};const pickerData=picker==='province'?catalog.provinces:picker==='city'?catalog.cities:picker==='type'?catalog.types:picker==='category'?catalog.categories:catalog.subcategories;const selected=picker==='province'?filters.province:picker==='city'?filters.city:picker==='type'?filters.type:picker==='category'?filters.category:filters.subcategory;
 const run=async()=>{setLoading(true);setErr('');try{const p:any={q,mode};if(filters.province)p.province=titleOf(filters.province);if(filters.city)p.city=titleOf(filters.city);if(filters.type)p.type=filters.type.slug||filters.type.name;if(filters.category)p.category_id=filters.category.id;if(filters.subcategory)p.subcategory_id=filters.subcategory.id;if(filters.min)p.min_price=filters.min;if(filters.max)p.max_price=filters.max;setData(await apiGet('search',p))}catch(e:any){setErr(e.message)}finally{setLoading(false)}};
 return <View style={{flex:1}}><ScrollView contentContainerStyle={{padding:14,paddingBottom:28}} keyboardShouldPersistTaps="handled"><View style={{minHeight:52,borderRadius:17,backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,paddingRight:44,paddingLeft:12,justifyContent:'center',position:'relative',marginBottom:9}}><View style={{position:'absolute',right:13}}><AppIcon name="magnify" size={22} color={palette.primary}/></View><TextInput value={q} onChangeText={setQ} onSubmitEditing={run} placeholder="نام کسب‌وکار یا محصول…" placeholderTextColor={palette.text2} style={{height:50,textAlign:'right',writingDirection:'rtl',fontSize:14,color:palette.text}}/></View>
  <View style={{flexDirection:'row-reverse',gap:7,marginBottom:10}}><Chip label="همه" active={mode==='all'} onPress={()=>setMode('all')}/><Chip label="کسب‌وکار" active={mode==='businesses'} onPress={()=>setMode('businesses')}/><Chip label="محصول" active={mode==='products'} onPress={()=>setMode('products')}/></View><Txt style={{fontSize:12.5,fontWeight:'800',color:palette.text2,marginBottom:7,textAlign:'right',width:'100%'}}>فیلترهای اصلی</Txt>
  <View style={{flexDirection:'row-reverse',gap:8,marginBottom:8}}><FilterBtnV5 label="استان" value={titleOf(filters.province)||'همه استان‌ها'} onPress={()=>setPicker('province')}/><FilterBtnV5 label="شهر" value={titleOf(filters.city)||'همه شهرها'} disabled={!filters.province} onPress={()=>setPicker('city')}/></View><View style={{flexDirection:'row-reverse',gap:8,marginBottom:8}}><FilterBtnV5 label="نوع فعالیت" value={titleOf(filters.type)||'همه انواع'} onPress={()=>setPicker('type')}/><FilterBtnV5 label="دسته‌بندی" value={titleOf(filters.category)||'همه دسته‌ها'} onPress={()=>setPicker('category')}/></View>
  <Pressable onPress={()=>setMore(v=>!v)} style={{minHeight:42,borderRadius:14,backgroundColor:palette.surface2,flexDirection:'row-reverse',alignItems:'center',justifyContent:'center',gap:7,marginBottom:9}}><AppIcon name={more?'chevron-up':'tune-variant'} size={18} color={palette.primary}/><Txt style={{fontSize:13,color:palette.primary,fontWeight:'800',textAlign:'center'}}>فیلترهای بیشتر؛ زیردسته و بازه قیمت</Txt></Pressable>
  {more?<View style={{marginBottom:9}}><FilterBtnV5 label="زیردسته" value={titleOf(filters.subcategory)||'همه زیردسته‌ها'} disabled={!filters.category} onPress={()=>setPicker('subcategory')}/><View style={{flexDirection:'row-reverse',gap:8,marginTop:8}}><View style={{flex:1}}><Txt style={{fontSize:11,color:palette.text2,marginBottom:4}}>حداقل قیمت</Txt><Field value={filters.min||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,min:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View><View style={{flex:1}}><Txt style={{fontSize:11,color:palette.text2,marginBottom:4}}>حداکثر قیمت</Txt><Field value={filters.max||''} onChangeText={(v:string)=>setFilters((f:any)=>({...f,max:v.replace(/\D/g,'')}))} placeholder="تومان" keyboardType="number-pad"/></View></View></View>:null}
  <PrimaryButton title={loading?'در حال جست‌وجو…':'جست‌وجو'} icon="magnify" onPress={run} disabled={loading}/>{err?<Txt style={{color:palette.danger,marginTop:9}}>{err}</Txt>:null}{data?<View style={{marginTop:12}}><Txt style={{fontSize:15.5,fontWeight:'900',marginBottom:8}}>نتایج جست‌وجو</Txt>{!(data.businesses||[]).length&&!(data.products||[]).length?<EmptyState title="نتیجه‌ای پیدا نشد" detail="فیلترها یا عبارت جست‌وجو را تغییر دهید."/>:null}{(data.businesses||[]).map((b:any)=><StoreCardV7 key={`b${b.id}`} b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/>)}{(data.products||[]).map((p:any)=><ProductCardV7 key={`p${p.id}`} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}</View>:null}</ScrollView><SelectSheet visible={!!picker} title={picker==='province'?'انتخاب استان':picker==='city'?'انتخاب شهر':picker==='type'?'نوع فعالیت':picker==='category'?'دسته‌بندی':'زیردسته'} items={pickerData||[]} selectedId={selected?.id||selected?.slug} onClose={()=>setPicker(null)} onSelect={onSelect}/></View>}

function ContactActionV5({d,b,onPress}:any){const unlocked=!!d.contact_unlocked;return <Pressable onPress={onPress} style={{minHeight:70,borderRadius:18,backgroundColor:palette.primary,borderWidth:1,borderColor:palette.primary,paddingHorizontal:48,alignItems:'center',justifyContent:'center',position:'relative',marginBottom:9}}><View style={{position:'absolute',right:12,width:30,height:30,borderRadius:10,backgroundColor:'rgba(255,255,255,.17)',alignItems:'center',justifyContent:'center'}}><AppIcon name={unlocked?'message-text-outline':'lock-outline'} size={18} color="#fff"/></View><Txt style={{fontSize:14.5,fontWeight:'900',color:'#fff',textAlign:'center',width:'100%'}}>{unlocked?'گفتگو با کسب‌وکار':'ارتباط با کسب‌وکار'}</Txt><Txt style={{fontSize:11.5,color:'#DDF3EA',textAlign:'center',width:'100%',marginTop:2}}>{unlocked?'دسترسی ارتباط برای شما فعال است':d.contact_paid_enabled&&d.contact_price_toman>0?`نمایش راه‌های تماس پس از پرداخت ${money(d.contact_price_toman)} تومان`:'ورود به مسیر ارتباط با کسب‌وکار'}</Txt><View style={{position:'absolute',left:11}}><AppIcon name="chevron-left" size={22} color="#fff"/></View></Pressable>}

function BusinessDetailV5({id,navigate}:any){
 const cached=mobileCacheV5.businessDetail[id];const [d,setD]=useState<any>(cached);const [loading,setLoading]=useState(!cached);const [err,setErr]=useState('');const [refreshing,setRefreshing]=useState(false);const load=async(refresh=false)=>{if(refresh)setRefreshing(true);else if(!d)setLoading(true);setErr('');try{const x=await apiGet('business.detail',{id});mobileCacheV5.businessDetail[id]=x;setD(x)}catch(e:any){setErr(e.message)}finally{setLoading(false);setRefreshing(false)}};useEffect(()=>{load(false)},[id]);if(loading&&!d)return <Loader/>;if(err&&!d)return <ErrorState message={err} onRetry={()=>load(false)}/>;const b=d.business;const contact=()=>navigate('chatThread',{businessId:b.id});
 return <ScrollView refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>load(true)} colors={[palette.primary]}/>} contentContainerStyle={{padding:14,paddingBottom:30}}><View style={{minHeight:82,paddingRight:66,justifyContent:'center',position:'relative',marginBottom:10}}><View style={{position:'absolute',right:0,width:52,height:52,borderRadius:17,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="storefront-outline" size={26} color={palette.primary}/></View><Txt style={{fontSize:19,fontWeight:'900',textAlign:'right',width:'100%'}}>{b.name}</Txt><Txt style={{fontSize:12.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:2}}>{[b.province,b.city].filter(Boolean).join('، ')}</Txt></View>
 {b.description?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,padding:13,marginBottom:9}}><Txt style={{fontSize:13,lineHeight:22,textAlign:'right',width:'100%'}}>{b.description}</Txt></View>:null}
 {!d.is_owner?<ContactActionV5 d={d} b={b} onPress={contact}/>:null}
 {d.contact_unlocked&&(b.public_phone||b.address)?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:'#CFE4DB',borderRadius:18,padding:13,marginBottom:9}}><Txt style={{fontSize:13.5,fontWeight:'900',marginBottom:7}}>راه‌های ارتباطی</Txt>{b.public_phone?<View style={{paddingRight:28,position:'relative',marginBottom:b.address?7:0}}><View style={{position:'absolute',right:0}}><AppIcon name="phone-outline" size={18} color={palette.primary}/></View><Txt style={{fontSize:13,textAlign:'right',width:'100%'}}>{b.public_phone}</Txt></View>:null}{b.address?<View style={{paddingRight:28,position:'relative'}}><View style={{position:'absolute',right:0}}><AppIcon name="map-marker-outline" size={18} color={palette.primary}/></View><Txt style={{fontSize:13,textAlign:'right',width:'100%'}}>{b.address}</Txt></View>:null}</View>:!d.is_owner?<View style={{backgroundColor:'#F5F8F6',borderWidth:1,borderColor:'#E2EAE6',borderRadius:17,padding:12,marginBottom:9,paddingRight:40,position:'relative'}}><View style={{position:'absolute',right:12,top:13}}><AppIcon name="shield-lock-outline" size={19} color={palette.text2}/></View><Txt style={{fontSize:12,color:palette.text2,textAlign:'right'}}>شناسه، شماره تماس و آدرس کامل قبل از فعال‌شدن دسترسی نمایش داده نمی‌شود.</Txt></View>:null}
 {!d.is_owner?<SecondaryButton title={d.is_following?'دنبال می‌کنید':'دنبال کردن'} icon={d.is_following?'heart':'heart-outline'} onPress={async()=>{await apiPost('follow.toggle',{business_id:b.id});await load(false)}}/>:null}
 <View style={{minHeight:38,justifyContent:'center',alignItems:'flex-end',marginTop:8,marginBottom:6}}><Txt style={{fontSize:16,fontWeight:'900'}}>محصولات</Txt></View>{(d.products||[]).map((p:any)=><ProductCardV7 key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}{!(d.products||[]).length?<EmptyState title="محصولی ثبت نشده"/>:null}</ScrollView>}

function ProductDetailV5({id,navigate}:any){const {width}=useWindowDimensions();const cached=mobileCacheV5.productDetail[id];const [d,setD]=useState<any>(cached);const [loading,setLoading]=useState(!cached);const [err,setErr]=useState('');const [uploading,setUploading]=useState(false);const load=async()=>{if(!d)setLoading(true);setErr('');try{const x=await apiGet('product.detail',{id});mobileCacheV5.productDetail[id]=x;setD(x)}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[id]);if(loading&&!d)return <Loader/>;if(err&&!d)return <ErrorState message={err} onRetry={load}/>;const p=d.product;const media=d.media||[];const contact=()=>navigate('chatThread',{businessId:p.business_id});const pick=async()=>{const r=await launchImageLibrary({mediaType:'mixed',selectionLimit:1});if(r.didCancel||!r.assets?.[0])return;setUploading(true);try{await uploadMedia(id,r.assets[0]);await load()}catch(e:any){setErr(e.message)}finally{setUploading(false)}};
 return <ScrollView contentContainerStyle={{padding:14,paddingBottom:30}}>{media.length?<ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false} style={{marginHorizontal:-14,marginBottom:12}}>{media.map((m:any)=>m.type==='video'?<View key={m.id} style={{width,paddingHorizontal:14}}><Video source={{uri:m.url}} style={{height:290,borderRadius:21,backgroundColor:'#101614'}} controls paused resizeMode="contain"/></View>:<View key={m.id} style={{width,paddingHorizontal:14}}><Image source={{uri:m.url}} style={{height:290,borderRadius:21,backgroundColor:palette.border}} resizeMode="cover"/></View>)}</ScrollView>:<View style={{height:210,borderRadius:21,backgroundColor:palette.surface2,alignItems:'center',justifyContent:'center',marginBottom:11}}><AppIcon name="image-outline" size={42} color={palette.text2}/></View>}
 <Txt style={{fontSize:19,fontWeight:'900',textAlign:'right',width:'100%'}}>{p.name}</Txt><Pressable onPress={()=>navigate('businessDetail',{id:p.business_id})}><Txt style={{fontSize:12.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:2}}>{p.business_name||''}</Txt></Pressable><Txt style={{fontSize:19,color:palette.primary,fontWeight:'900',textAlign:'right',width:'100%',marginVertical:8}}>{Number(p.price||0)>0?`${money(p.price)} تومان`:'قیمت توافقی'}</Txt>{p.description?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,padding:13,marginBottom:9}}><Txt style={{fontSize:13,lineHeight:22,textAlign:'right',width:'100%'}}>{p.description}</Txt></View>:null}{!d.is_owner?<PrimaryButton title="گفتگوی رایگان در اپلیکیشن" icon="message-text-outline" onPress={contact}/>:null}{d.is_owner?<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,padding:13,marginTop:9}}><Txt style={{fontSize:15.5,fontWeight:'900',marginBottom:4}}>مدیریت رسانه</Txt><Txt style={{fontSize:12,color:palette.text2,marginBottom:8}}>فضا: {d.quota?.storage_used_mb||0} از {d.quota?.storage_limit_mb||0} مگابایت</Txt><PrimaryButton title={uploading?'در حال بارگذاری…':'افزودن عکس یا ویدئو'} icon="image-plus" onPress={pick} disabled={uploading}/></View>:null}</ScrollView>}

function MyBusinessV5({navigate,mode='all'}:any){const cached=mobileCacheV5.mine;const [biz,setBiz]=useState<any[]>(cached?.businesses||[]);const [products,setProducts]=useState<any[]>(cached?.products||[]);const [loading,setLoading]=useState(!cached);const [err,setErr]=useState('');const load=async()=>{if(!mobileCacheV5.mine)setLoading(true);try{const [b,p]=await Promise.all([apiGet('business.mine'),apiGet('product.mine')]);mobileCacheV5.mine={businesses:b.businesses||[],products:p.products||[]};mobileCacheV5.mineAt=Date.now();setBiz(b.businesses||[]);setProducts(p.products||[]);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{if(!mobileCacheV5.mine||Date.now()-(mobileCacheV5.mineAt||0)>60000)load()},[]);if(loading&&!biz.length)return <Loader/>;if(err&&!biz.length)return <ErrorState message={err} onRetry={load}/>;return <ScrollView contentContainerStyle={{padding:14,paddingBottom:28}}>{mode!=='products'?<><View style={{minHeight:44,justifyContent:'center',alignItems:'flex-end',position:'relative',marginBottom:7}}><Txt style={{fontSize:17,fontWeight:'900',textAlign:'right',width:'100%'}}>کسب‌وکارهای من</Txt><Pressable onPress={()=>navigate('createBusiness')} style={{position:'absolute',left:0,width:38,height:38,borderRadius:13,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="plus" size={21} color={palette.primary}/></Pressable></View>{biz.length?biz.map(b=><View key={b.id} style={{marginBottom:14}}><StoreCardV7 b={b} onPress={()=>navigate('businessDetail',{id:b.id})}/><SecondaryButton title="دنبال‌کننده‌های این کسب‌وکار" icon="account-group-outline" onPress={()=>navigate('followers',{id:b.id})}/></View>):<EmptyState title="هنوز کسب‌وکاری ندارید"/>}</>:null}{mode!=='businesses'&&biz.length?<><View style={{minHeight:44,justifyContent:'center',alignItems:'flex-end',position:'relative',marginTop:8,marginBottom:7}}><Txt style={{fontSize:17,fontWeight:'900',textAlign:'right',width:'100%'}}>محصولات من</Txt><Pressable onPress={()=>navigate('createProduct',{businesses:biz})} style={{position:'absolute',left:0,width:38,height:38,borderRadius:13,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="plus" size={21} color={palette.primary}/></Pressable></View>{products.map(p=><ProductCardV7 key={p.id} p={p} onPress={()=>navigate('productDetail',{id:p.id})}/>)}</>:null}</ScrollView>}

function AccountRowV5({title,subtitle,icon,onPress}:any){return <Pressable onPress={onPress} style={{minHeight:64,borderRadius:17,backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,paddingRight:58,paddingLeft:36,justifyContent:'center',position:'relative',marginBottom:8}}><View style={{position:'absolute',right:10,width:36,height:36,borderRadius:12,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name={icon} size={19} color={palette.primary}/></View><View style={{width:'100%',alignItems:'flex-end'}}><Txt style={{fontSize:14,fontWeight:'800',textAlign:'right',width:'100%'}}>{title}</Txt>{subtitle?<Txt style={{fontSize:11.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:1}}>{subtitle}</Txt>:null}</View><View style={{position:'absolute',left:10}}><AppIcon name="chevron-left" size={22} color={palette.text2}/></View></Pressable>}

function AccountV5({boot,setBoot,navigate,onLogout}:any){const u=boot?.user||{};const prefs=boot?.preferences||{};const name=u.display_name||`${u.first_name||''} ${u.last_name||''}`.trim()||'کاربر';const toggle=async(kind:string,val:boolean)=>{await apiPost('preferences.update',{kind,enabled:val});const b=await apiGet('bootstrap');setBoot(b)};return <ScrollView contentContainerStyle={{padding:14,paddingBottom:28}}><View style={{backgroundColor:palette.primary,borderRadius:20,minHeight:118,paddingRight:70,paddingLeft:14,paddingVertical:16,justifyContent:'center',position:'relative',marginBottom:11}}><View style={{position:'absolute',right:14,width:44,height:44,borderRadius:14,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center'}}><AppIcon name="account-outline" size={24} color={palette.primaryDark}/></View><Txt style={{fontSize:17.5,fontWeight:'900',color:'#fff',textAlign:'right',width:'100%'}}>{name}</Txt>{u.username?<Txt style={{fontSize:12,color:palette.primarySoft,textAlign:'right',width:'100%',marginTop:2}}>@{u.username}</Txt>:null}<Txt style={{fontSize:11.5,color:palette.primarySoft,textAlign:'right',width:'100%',marginTop:3}}>{[u.province,u.city].filter(Boolean).join('، ')||'موقعیت پروفایل ثبت نشده'}</Txt></View><AccountRowV5 title="فرصت‌های تجاری و گزارش من" subtitle="درخواست خرید، عرضه، پیشنهاد همکاری و آموزش" icon="handshake-outline" onPress={()=>navigate('commercialPage')}/><AccountRowV5 title="پشتیبانی" subtitle="گفتگو با پشتیبان و مدیر سامانه" icon="headset" onPress={()=>navigate('supportPage')}/><AdminEntry user={u} navigate={navigate} onBoot={(b:any)=>{Object.assign(mobileCacheV5,{home:null,mine:null,support:null,businessDetail:{},productDetail:{}});setBoot(b);}}/><AccountRowV5 title="حریم خصوصی و دسترسی‌ها" icon="shield-check-outline" onPress={()=>navigate('privacy')}/><AccountRowV5 title="پلن و فضای رسانه" icon="star-outline" onPress={()=>navigate('plans')}/><AccountRowV5 title="نوبت‌های من" icon="calendar-check-outline" onPress={()=>navigate('appointments')}/><AccountRowV5 title="کمپین‌ها" icon="bullhorn-outline" onPress={()=>navigate('campaigns')}/><AccountRowV5 title="کسب‌وکارهای دنبال‌شده" subtitle="فهرست کسب‌وکارهایی که دنبال می‌کنید" icon="heart-outline" onPress={()=>navigate('following')}/>{u.is_admin?<AccountRowV5 title="ورود با کاربر آزمایشی" icon="flask-outline" onPress={async()=>{const r=await apiPost('admin.test_user.login',{});await saveAdminSession();await setToken(r.token);Object.assign(mobileCacheV5,{home:null,mine:null,support:null,businessDetail:{},productDetail:{}});const b=await apiGet('bootstrap');setBoot(b)}}/>:null}<View style={{backgroundColor:'#fff',borderWidth:1,borderColor:palette.border,borderRadius:18,paddingHorizontal:13,marginVertical:3}}><ToggleRow title="دیده‌بان بازار" value={!!prefs.market_watch} onPress={()=>toggle('market_watch',!prefs.market_watch)}/>{prefs.daily_tip!==null&&prefs.daily_tip!==undefined?<ToggleRow title="نکته روزانه کسب‌وکار" value={!!prefs.daily_tip} onPress={()=>toggle('daily_tip',!prefs.daily_tip)}/>:null}</View><View style={{marginTop:9}}><SecondaryButton title="خروج از حساب" icon="logout" onPress={onLogout}/></View></ScrollView>}

function SupportV5(){const cached=mobileCacheV5.support;const [d,setD]=useState<any>(cached||{messages:[]});const [body,setBody]=useState('');const [loading,setLoading]=useState(!cached);const [err,setErr]=useState('');const [sending,setSending]=useState(false);
 const full=async()=>{try{const x=await apiGet('support.mine');mobileCacheV5.support=x;setD(x);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};
 const poll=async()=>{try{const c=mobileCacheV5.support;const last=(c?.messages||[]).reduce((m:number,x:any)=>Math.max(m,Number(x.id)||0),0);const x=await apiGet('support.mine',last?{after_id:last}:{});if(!c||!last){mobileCacheV5.support=x;setD(x);return}const incoming=x.messages||[];if(incoming.length){const ids=new Set((c.messages||[]).map((m:any)=>String(m.id)));const merged=[...(c.messages||[]),...incoming.filter((m:any)=>!ids.has(String(m.id)))];const next={...c,request:x.request||c.request,messages:merged};mobileCacheV5.support=next;setD(next)}}catch{}};
 useEffect(()=>{full();const t=setInterval(poll,1200);return()=>clearInterval(t)},[]);
 const send=async()=>{const text=body.trim();if(!text||sending)return;setSending(true);setBody('');const temp={id:`tmp-${Date.now()}`,sender_role:'user',body:text,created_at:new Date().toISOString().slice(0,19).replace('T',' ')};setD((x:any)=>({...x,messages:[...(x.messages||[]),temp]}));try{await apiPost('support.send',{body:text});await full()}catch(e:any){setErr(e.message);setBody(text)}finally{setSending(false)}};
 if(loading&&!d?.messages?.length)return <Loader/>;const status=supportStatusV5(String(d?.request?.status||'queued'));return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView contentContainerStyle={{padding:14,paddingBottom:18}}>{err?<Txt style={{color:palette.danger,marginBottom:8}}>{err}</Txt>:null}<View style={{minHeight:54,alignItems:'flex-end',justifyContent:'center',marginBottom:9}}><Txt style={{fontSize:16.5,fontWeight:'900',textAlign:'right'}}>گفت‌وگو با پشتیبانی</Txt><Txt style={{fontSize:11.5,color:palette.text2,textAlign:'right',marginTop:1}}>{d.request?status:'پیام شما مستقیماً برای پشتیبانی سامانه ارسال می‌شود.'}</Txt></View>{(d.messages||[]).map((m:any)=><View key={String(m.id)} style={{maxWidth:'82%',alignSelf:m.sender_role==='user'?'flex-end':'flex-start',backgroundColor:m.sender_role==='user'?palette.primarySoft:'#fff',borderWidth:m.sender_role==='user'?0:1,borderColor:palette.border,borderRadius:18,paddingHorizontal:12,paddingVertical:9,marginBottom:8}}><Txt style={{fontSize:13,textAlign:'right'}}>{m.body}</Txt><Txt style={{fontSize:10.5,color:palette.text2,textAlign:'right',marginTop:3}}>{m.created_at}</Txt></View>)}</ScrollView><View style={{backgroundColor:'#fff',borderTopWidth:1,borderTopColor:palette.border,paddingHorizontal:10,paddingVertical:9}}><View style={{flexDirection:'row',alignItems:'flex-end',gap:8}}><Pressable disabled={sending||!body.trim()} onPress={send} style={{width:48,height:48,borderRadius:16,backgroundColor:palette.primary,alignItems:'center',justifyContent:'center',opacity:(sending||!body.trim()) ? .5 : 1}}><AppIcon name="send" size={21} color="#fff"/></Pressable><TextInput value={body} onChangeText={setBody} placeholder="پیام شما…" placeholderTextColor={palette.text2} multiline style={{flex:1,maxHeight:110,minHeight:48,borderRadius:17,backgroundColor:palette.surface2,paddingHorizontal:13,paddingVertical:10,textAlign:'right',writingDirection:'rtl',color:palette.text,fontSize:13.5}}/></View></View></KeyboardAvoidingView>}

