function BusinessFormV7({onDone,initial}:any){
 const init=initial?.business||initial||{};const [f,setF]=useState<any>({name:init.name||'',manager_name:init.manager_name||'',phone:init.phone||'',public_phone:init.public_phone||'',address:init.address||'',description:init.description||'',province:init.province||null,city:init.city||null,type:initial?.types?.[0]||null,category:initial?.categories?.[0]||null});
 const [catalog,setCatalog]=useState<any>({provinces:[],cities:[],types:[],categories:[]});const [picker,setPicker]=useState<string|null>(null);const [asset,setAsset]=useState<any>(null);const [busy,setBusy]=useState(false);const [err,setErr]=useState('');const edit=!!init.id;
 const display=(x:any)=>typeof x==='string'?x:titleOf(x);const loadFilters=async(extra:any={})=>{try{const x=await apiGet('search.filters',extra);setCatalog((c:any)=>({...c,...x}));return x}catch(e:any){setErr(e.message);return null}};useEffect(()=>{(async()=>{const x=await loadFilters();if(x&&typeof init.province==='string'&&init.province){const pr=(x.provinces||[]).find((z:any)=>titleOf(z)===init.province);if(pr){const y=await loadFilters({province_id:pr.id});const ci=(y?.cities||[]).find((z:any)=>titleOf(z)===init.city);setF((v:any)=>({...v,province:pr,city:ci||init.city}))}}})()},[]);
 const select=async(x:any)=>{if(picker==='province'){setF((v:any)=>({...v,province:x,city:null}));await loadFilters({province_id:x.id})}else setF((v:any)=>({...v,[picker as string]:x}));setPicker(null)};
 const pick=async()=>{const r=await launchImageLibrary({mediaType:'photo',selectionLimit:1});if(!r.didCancel&&r.assets?.[0])setAsset(r.assets[0])};
 const submit=async()=>{if(!f.name.trim()){setErr('نام کسب‌وکار را وارد کنید.');return}if(!f.province||!f.city){setErr('استان و شهر را انتخاب کنید.');return}setBusy(true);setErr('');try{const body={name:f.name,manager_name:f.manager_name,phone:f.phone,public_phone:f.public_phone,province:display(f.province),city:display(f.city),address:f.address,description:f.description,type_slugs:f.type?.slug?[f.type.slug]:[],category_ids:f.category?.id?[f.category.id]:[]};let id=Number(init.id||0);if(edit)await apiPost('business.update',{business_id:id,...body});else{const r=await apiPost('business.create',body);id=Number(r.business_id||0)}if(asset&&id>0)await uploadBusinessMedia(id,asset);onDone()}catch(e:any){setErr(e.message)}finally{setBusy(false)}};
 const items=picker==='province'?catalog.provinces:picker==='city'?catalog.cities:picker==='type'?catalog.types:catalog.categories;
 return <ScrollView contentContainerStyle={s.page} keyboardShouldPersistTaps="handled"><View style={{alignItems:'center',marginBottom:14}}><Pressable onPress={pick} style={{width:112,height:112,borderRadius:30,backgroundColor:palette.primarySoft,alignItems:'center',justifyContent:'center',overflow:'hidden',borderWidth:1,borderColor:palette.border}}>{asset?.uri?<Image source={{uri:asset.uri}} style={{width:'100%',height:'100%'}} resizeMode="cover"/>:init.cover?.url?<Image source={{uri:init.cover.url}} style={{width:'100%',height:'100%'}} resizeMode="cover"/>:<AppIcon name="camera-plus-outline" size={34} color={palette.primary}/>}</Pressable><Txt style={{fontSize:12,color:palette.text2,textAlign:'center',marginTop:7}}>تصویر کسب‌وکار {edit?'را تغییر دهید':'اضافه کنید'}</Txt></View><Txt style={s.label}>نام کسب‌وکار</Txt><Field value={f.name} onChangeText={(v:string)=>setF({...f,name:v})} placeholder="نام کسب‌وکار"/><Txt style={s.label}>نام مدیر</Txt><Field value={f.manager_name} onChangeText={(v:string)=>setF({...f,manager_name:v})} placeholder="نام مدیر"/><Txt style={s.label}>شماره تماس</Txt><Field value={f.phone} onChangeText={(v:string)=>setF({...f,phone:v})} placeholder="شماره تماس" keyboardType="phone-pad"/><Txt style={s.label}>استان</Txt><FilterRow label="" value={display(f.province)||'انتخاب استان'} onPress={()=>setPicker('province')}/><Txt style={s.label}>شهر</Txt><FilterRow label="" value={display(f.city)||'انتخاب شهر'} onPress={()=>{if(!f.province){setErr('ابتدا استان را انتخاب کنید.');return}setPicker('city')}}/><Txt style={s.label}>نوع فعالیت</Txt><FilterRow label="" value={display(f.type)||'انتخاب نوع فعالیت'} onPress={()=>setPicker('type')}/><Txt style={s.label}>دسته‌بندی</Txt><FilterRow label="" value={display(f.category)||'انتخاب دسته‌بندی'} onPress={()=>setPicker('category')}/><Txt style={s.label}>آدرس</Txt><Field value={f.address} onChangeText={(v:string)=>setF({...f,address:v})} placeholder="آدرس"/><Txt style={s.label}>توضیحات</Txt><Field value={f.description} onChangeText={(v:string)=>setF({...f,description:v})} placeholder="معرفی کوتاه" multiline/>{err?<Txt style={s.errorText}>{err}</Txt>:null}<PrimaryButton title={busy?'در حال ذخیره…':edit?'ذخیره تغییرات':'ثبت کسب‌وکار'} onPress={submit} disabled={busy}/><SelectSheet visible={!!picker} title={picker==='province'?'انتخاب استان':picker==='city'?'انتخاب شهر':picker==='type'?'انتخاب نوع فعالیت':'انتخاب دسته‌بندی'} items={items||[]} selectedId={(picker==='province'?f.province:picker==='city'?f.city:picker==='type'?f.type:f.category)?.id||(picker==='type'?f.type?.slug:undefined)} onSelect={select} onClose={()=>setPicker(null)}/></ScrollView>
}
function EditBusinessV7({id,onDone}:any){const [d,setD]=useState<any>();const [err,setErr]=useState('');useEffect(()=>{apiGet('business.detail',{id,_t:Date.now()}).then(setD).catch((e:any)=>setErr(e.message))},[id]);if(err)return <ErrorState message={err}/>;if(!d)return <Loader/>;return <BusinessFormScreen initial={d} onDone={onDone}/>}
function SupportV7(){const [d,setD]=useState<any>(mobileCacheV5.support||{messages:[]});const [body,setBody]=useState('');const [loading,setLoading]=useState(!mobileCacheV5.support);const [err,setErr]=useState('');const [sending,setSending]=useState(false);const [thread,setThread]=useState<number>(Number(mobileCacheV5.support?.thread_id||mobileCacheV5.support?.request?.thread_id||0));let alive=true;
 const full=async()=>{try{const x=await apiGet('support.mine',{_t:Date.now(),thread_id:thread||undefined});mobileCacheV5.support=x;setD(x);setThread(Number(x.thread_id||x.request?.thread_id||thread||0));setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};
 const poll=async()=>{try{const c=mobileCacheV5.support||d;const t=Number(thread||c?.thread_id||c?.request?.thread_id||0);const last=(c?.messages||[]).reduce((m:number,x:any)=>Math.max(m,Number(x.id)||0),0);const x=await apiGet('support.mine',{after_id:last,thread_id:t||undefined,_t:Date.now()});if(!alive)return;const incoming=x.messages||[];const ids=new Set((c?.messages||[]).map((m:any)=>String(m.id)));const merged=[...(c?.messages||[]),...incoming.filter((m:any)=>!ids.has(String(m.id)))];const next={...c,...x,messages:merged};mobileCacheV5.support=next;setD(next);if(x.thread_id)setThread(Number(x.thread_id))}catch{}};
 useEffect(()=>{alive=true;full();const t=setInterval(poll,600);const sub=AppState.addEventListener('change',(st:string)=>{if(st==='active'){full();poll()}});return()=>{alive=false;clearInterval(t);sub.remove()}},[thread]);
 const send=async()=>{const text=body.trim();if(!text||sending)return;setSending(true);setBody('');try{await apiPost('support.send',{body:text});await full()}catch(e:any){setErr(e.message);setBody(text)}finally{setSending(false)}};
 if(loading&&!d?.messages?.length)return <Loader/>;const status=supportStatusV5(String(d?.request?.status||'queued'));return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView contentContainerStyle={{padding:14,paddingBottom:18}}>{err?<Txt style={{color:palette.danger,marginBottom:8,textAlign:'right',width:'100%'}}>{err}</Txt>:null}<View style={{minHeight:54,alignItems:'flex-end',justifyContent:'center',marginBottom:9}}><Txt style={{fontSize:16.5,fontWeight:'900',textAlign:'right',width:'100%'}}>گفت‌وگو با پشتیبانی</Txt><Txt style={{fontSize:11.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:1}}>{d.request?status:'پیام شما مستقیماً برای پشتیبانی سامانه ارسال می‌شود.'}</Txt></View>{(d.messages||[]).map((m:any)=><View key={String(m.id)} style={{maxWidth:'82%',alignSelf:m.sender_role==='user'?'flex-end':'flex-start',backgroundColor:m.sender_role==='user'?palette.primarySoft:'#fff',borderWidth:m.sender_role==='user'?0:1,borderColor:palette.border,borderRadius:18,paddingHorizontal:12,paddingVertical:9,marginBottom:8}}><Txt style={{fontSize:13,textAlign:'right',width:'100%'}}>{m.body}</Txt><Txt style={{fontSize:10.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:3}}>{m.created_at}</Txt></View>)}</ScrollView><View style={{backgroundColor:'#fff',borderTopWidth:1,borderTopColor:palette.border,paddingHorizontal:10,paddingVertical:9}}><View style={{flexDirection:'row',alignItems:'flex-end',gap:8}}><Pressable disabled={sending||!body.trim()} onPress={send} style={{width:48,height:48,borderRadius:16,backgroundColor:palette.primary,alignItems:'center',justifyContent:'center',opacity:(sending||!body.trim()) ? .5 : 1}}><AppIcon name="send" size={21} color="#fff"/></Pressable><TextInput value={body} onChangeText={setBody} placeholder="پیام شما…" placeholderTextColor={palette.text2} multiline style={{flex:1,maxHeight:110,minHeight:48,borderRadius:17,backgroundColor:palette.surface2,paddingHorizontal:13,paddingVertical:10,textAlign:'right',writingDirection:'rtl',color:palette.text,fontSize:13.5}}/></View></View></KeyboardAvoidingView>}
function SupportV6(){const cached=mobileCacheV5.support;const [d,setD]=useState<any>(cached||{messages:[]});const [body,setBody]=useState('');const [loading,setLoading]=useState(!cached);const [err,setErr]=useState('');const [sending,setSending]=useState(false);const full=async()=>{try{const x=await apiGet('support.mine',{_t:Date.now()});mobileCacheV5.support=x;setD(x);setErr('')}catch(e:any){setErr(e.message)}finally{setLoading(false)}};const poll=async()=>{if(supportPollBusyV6)return;supportPollBusyV6=true;try{const c=mobileCacheV5.support;const last=(c?.messages||[]).reduce((m:number,x:any)=>Math.max(m,Number(x.id)||0),0);const x=await apiGet('support.mine',{after_id:last,_t:Date.now()});if(!c||!last){mobileCacheV5.support=x;setD(x)}else{const incoming=x.messages||[];if(incoming.length||x.request?.status!==c.request?.status){const ids=new Set((c.messages||[]).map((m:any)=>String(m.id)));const merged=[...(c.messages||[]),...incoming.filter((m:any)=>!ids.has(String(m.id)))];const next={...c,request:x.request||c.request,messages:merged};mobileCacheV5.support=next;setD(next)}}}catch{}finally{supportPollBusyV6=false}};useEffect(()=>{full();const t=setInterval(poll,750);const sub=AppState.addEventListener('change',(st:string)=>{if(st==='active'){full();poll()}});return()=>{clearInterval(t);sub.remove()}},[]);const send=async()=>{const text=body.trim();if(!text||sending)return;setSending(true);setBody('');const temp={id:`tmp-${Date.now()}`,sender_role:'user',body:text,created_at:new Date().toISOString()};setD((x:any)=>({...x,messages:[...(x.messages||[]),temp]}));try{await apiPost('support.send',{body:text});await full()}catch(e:any){setErr(e.message);setBody(text)}finally{setSending(false)}};if(loading&&!d?.messages?.length)return <Loader/>;const status=supportStatusV5(String(d?.request?.status||'queued'));return <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined}><ScrollView contentContainerStyle={{padding:14,paddingBottom:18}}>{err?<Txt style={{color:palette.danger,marginBottom:8,textAlign:'right',width:'100%'}}>{err}</Txt>:null}<View style={{minHeight:54,alignItems:'flex-end',justifyContent:'center',marginBottom:9}}><Txt style={{fontSize:16.5,fontWeight:'900',textAlign:'right',width:'100%'}}>گفت‌وگو با پشتیبانی</Txt><Txt style={{fontSize:11.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:1}}>{d.request?status:'پیام شما مستقیماً برای پشتیبانی سامانه ارسال می‌شود.'}</Txt></View>{(d.messages||[]).map((m:any)=><View key={String(m.id)} style={{maxWidth:'82%',alignSelf:m.sender_role==='user'?'flex-end':'flex-start',backgroundColor:m.sender_role==='user'?palette.primarySoft:'#fff',borderWidth:m.sender_role==='user'?0:1,borderColor:palette.border,borderRadius:18,paddingHorizontal:12,paddingVertical:9,marginBottom:8}}><Txt style={{fontSize:13,textAlign:'right',width:'100%'}}>{m.body}</Txt><Txt style={{fontSize:10.5,color:palette.text2,textAlign:'right',width:'100%',marginTop:3}}>{m.created_at}</Txt></View>)}</ScrollView><View style={{backgroundColor:'#fff',borderTopWidth:1,borderTopColor:palette.border,paddingHorizontal:10,paddingVertical:9}}><View style={{flexDirection:'row',alignItems:'flex-end',gap:8}}><Pressable disabled={sending||!body.trim()} onPress={send} style={{width:48,height:48,borderRadius:16,backgroundColor:palette.primary,alignItems:'center',justifyContent:'center',opacity:(sending||!body.trim()) ? .5 : 1}}><AppIcon name="send" size={21} color="#fff"/></Pressable><TextInput value={body} onChangeText={setBody} placeholder="پیام شما…" placeholderTextColor={palette.text2} multiline style={{flex:1,maxHeight:110,minHeight:48,borderRadius:17,backgroundColor:palette.surface2,paddingHorizontal:13,paddingVertical:10,textAlign:'right',writingDirection:'rtl',color:palette.text,fontSize:13.5}}/></View></View></KeyboardAvoidingView>}
